"""Theme Radar score engine — compressed payload (restore-safe)."""
from __future__ import annotations

import base64
import sys
import types
import zlib

_B64 = ""

def _load():
    src = zlib.decompress(base64.b64decode(_B64)).decode()
    mod = types.ModuleType(__name__ + "_impl")
    mod.__file__ = __file__
    mod.__package__ = __package__
    g = mod.__dict__
    g["__name__"] = __name__
    g["__package__"] = __package__
    g["__file__"] = __file__
    exec(compile(src, "score_engine_core.py", "exec"), g)
    return mod

_impl = _load()
for _k, _v in _impl.__dict__.items():
    if _k.startswith("_") and _k not in ("_WEIGHT_OVERRIDES",):
        continue
    globals()[_k] = _v

main = _impl.main

if __name__ == "__main__":
    main()
